package com.miaa.cas.journal.domain;

public enum VoucherType {
    STANDARD, ADJUSTING, REVERSAL, OPENING, RECURRING, CLOSING,
    /** Generated by a sub-ledger document (invoice, payment, ...) that was approved in its own module. */
    SUBLEDGER;

    /** Types a user can create directly; the others are generated by the system from a source. */
    public boolean isManuallyCreatable() {
        return this == STANDARD || this == ADJUSTING || this == OPENING;
    }

    /** Types allowed to post into a soft-closed period. */
    public boolean allowedInSoftClosedPeriod() {
        return this == ADJUSTING || this == CLOSING;
    }
}
